import { exec, execFile } from 'child_process';

// VULNERABLE — user input passed to shell
app.post('/convert', (req, res) => {
  const filename = req.body.filename;  // e.g., 'report.pdf'

  // Attack: filename = 'report.pdf; cat /etc/passwd; echo '
  // Shell executes: convert report.pdf; cat /etc/passwd; echo  output.png
  // /etc/passwd is now returned to the attacker
  exec(`convert ${filename} output.png`, (err, stdout) => {
    res.send(stdout);
  });
});

// SAFE APPROACH 1 — execFile (bypasses shell entirely)
app.post('/convert', (req, res) => {
  const filename = req.body.filename;

  // Validate input first — only allow safe filenames
  if (!/^[\w\-]+\.pdf$/.test(filename)) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  // execFile passes arguments as an array — no shell interpretation
  // ';' in the filename becomes a literal argument, not a shell separator
  execFile('convert', [filename, 'output.png'], (err, stdout) => {
    if (err) return res.status(500).json({ error: 'Conversion failed' });
    res.send(stdout);
  });
});

