import path from 'path';
import fs from 'fs';

// VULNERABLE — user controls file path
app.get('/files/:filename', (req, res) => {
  const filename = req.params.filename;

  // Attack: filename = '../../etc/passwd'
  // Reads: /app/uploads/../../etc/passwd  →  /etc/passwd
  // Returns the system password file!
  const filePath = `/app/uploads/${filename}`;
  res.sendFile(filePath);
});

// SAFE — resolve and validate the path stays within allowed directory
const UPLOAD_DIR = path.resolve('/app/uploads');

app.get('/files/:filename', (req, res) => {
  const filename = req.params.filename;

  // path.resolve() handles ../ and symlinks
  const requestedPath = path.resolve(UPLOAD_DIR, filename);

  // CRITICAL CHECK: does the resolved path start with the allowed directory?
  if (!requestedPath.startsWith(UPLOAD_DIR + path.sep)) {
    // '../' attack detected — reject
    return res.status(403).json({ error: 'Access denied' });
  }

  // Safe to serve
  res.sendFile(requestedPath);
});

// ADDITIONAL: validate filename characters
function isSafeFilename(name: string): boolean {
  // Only allow alphanumeric, dash, underscore, dot
  // Block: ../, /, \, null bytes, %00
  return /^[\w\-\.]+$/.test(name) && !name.includes('..');
}
